function normalizeUrl(rawUrl, platform) {
  try {
    const u = new URL(rawUrl.trim());
    if (platform === 'pantip' || u.hostname.includes('pantip.com')) {
      const m = u.pathname.match(/\/topic\/(\d+)/);
      return m ? `https://pantip.com/topic/${m[1]}` : u.origin + u.pathname;
    }
    if (platform === 'facebook_group' || u.hostname.includes('facebook.com')) {
      const keepParams = ['story_fbid', 'id', 'post_id'];
      const newParams = new URLSearchParams();
      keepParams.forEach(p => { if (u.searchParams.has(p)) newParams.set(p, u.searchParams.get(p)); });
      const qs = newParams.toString();
      return u.origin + u.pathname + (qs ? '?' + qs : '');
    }
    return u.origin + u.pathname;
  } catch (e) {
    return rawUrl.trim();
  }
}

const body = $json.body || $json;
const rawUrl = body.post_url || '';
const platform = body.platform || 'pantip';
const normalized = normalizeUrl(rawUrl, platform);

return [{
  json: {
    post_url: normalized,
    original_url: rawUrl,
    question_text: String(body.question_text || '').trim(),
    platform: platform,
    requested_by: body.requested_by || 'Discord User'
  }
}];

const req = $('Platform-Aware Normalize Post URL').first().json;
const rawSols = $input.first()?.json || [];
const solutions = (Array.isArray(rawSols) ? rawSols : (rawSols.data || [rawSols])).map(s => ({
  id: String(s.id),
  titleEn: s.titleEn || '',
  titleTh: s.titleTh || '',
  descEn: s.content?.en?.hero?.description || s.descEn || '',
  descTh: s.content?.th?.hero?.description || s.descTh || '',
  url: s.url || `https://www.syaco.co.th${s.link || `/solutions/${s.id}`}`
})).filter(s => s.titleEn || s.titleTh);

const voiceGuidelines = {
  pantip: 'Tone: Polite, friendly Thai senior engineer peer. Start directly with a practical solution or architecture diagram/concept. No sales pitch.',
  blognone: 'Tone: Technical, concise, engineering-focused. Discuss trade-offs, architecture, and technology choices.',
  blockdit: 'Tone: Structured problem breakdown and step-by-step solution. Professional and easy to follow.',
  facebook_group: 'Tone: Direct troubleshooting, practical advice, conversational and helpful.'
};

const prompt = [
  'You are an Enterprise Lead Qualification and Technical Advisory AI for SyaCo (https://www.syaco.co.th).',
  '',
  '## Task:',
  '1. Evaluate whether the user question represents a genuine Enterprise/B2B need (leadFit: HIGH / MEDIUM / LOW).',
  '2. Determine whether SyaCo has relevant expertise to answer this question concretely (canAnswer: boolean).',
  '3. Identify the best matching SyaCo solution (if any).',
  '4. Draft a high-value, practical technical response tailored to the platform.',
  '',
  `## Platform: ${req.platform}`,
  `Voice Guidelines: ${voiceGuidelines[req.platform] || voiceGuidelines.pantip}`,
  '',
  '## Target Thread Content:',
  `URL: ${req.post_url}`,
  `Question: ${req.question_text}`,
  '',
  '## SyaCo Published Solutions Catalog:',
  JSON.stringify(solutions, null, 2),
  '',
  '## Strict Writing & Anti-Spam Rules:',
  '- Answer the user\'s question FIRST with actionable, concrete engineering insights.',
  '- The answer MUST be 100% useful and standalone even without any link.',
  '- Do NOT fabricate statistics, fake client names, or exaggerated percentages.',
  '- Backlink Rule: Include a SyaCo solution URL ONLY if leadFit is HIGH/MEDIUM and the solution directly helps solve their problem. Otherwise set linkIncluded = false and suggestedAnchor = "".',
  '- Disclosure Rule: If a SyaCo link is included, you MUST include a natural, transparent disclosure in Thai (e.g. "Disclosure: ผมมาจากทีม SyaCo...").',
  '- Never repeat the user\'s question. Jump straight into the technical advice.',
  '',
  'Return valid JSON only matching the schema.'
].join('\n');

const geminiBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.6,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        leadFit: { type: 'STRING', enum: ['HIGH', 'MEDIUM', 'LOW'] },
        canAnswer: { type: 'BOOLEAN' },
        matchedSolutionId: { type: 'STRING' },
        matchScore: { type: 'NUMBER' },
        relevanceReason: { type: 'STRING' },
        matchedProblem: { type: 'STRING' },
        answer: { type: 'STRING' },
        linkIncluded: { type: 'BOOLEAN' },
        linkReason: { type: 'STRING' },
        suggestedAnchor: { type: 'STRING' }
      },
      required: ['leadFit', 'canAnswer', 'matchScore', 'relevanceReason', 'matchedProblem', 'answer', 'linkIncluded', 'suggestedAnchor']
    }
  }
};

return [{
  json: {
    req,
    solutions,
    geminiBody
  }
}];

const parent = $('Build Lead Qualification & Draft Prompt').first().json;
const req = parent.req;
const solutions = parent.solutions;

const candidates = $input.first()?.json?.candidates || [];
const rawText = candidates[0]?.content?.parts?.[0]?.text || '{}';
let data = {};
try {
  data = JSON.parse(rawText);
} catch (e) {
  throw new Error('Failed to parse Gemini evaluation output: ' + e.message);
}

let score = Number(data.matchScore || 0);
if (score > 1) {
  score = score / 100;
}
if (score > 0.999) score = 0.999;
if (score < 0) score = 0;
score = Math.round(score * 1000) / 1000;

const matchedSol = solutions.find(s => s.id === String(data.matchedSolutionId)) || solutions[0] || {};
const isQualified = data.leadFit !== 'LOW' && data.canAnswer === true && (score >= 0.70);
const status = isQualified ? 'pending_review' : 'skipped';

let solUrl = matchedSol.url || '';
if (solUrl && data.linkIncluded) {
  const utm = `?utm_source=${encodeURIComponent(req.platform)}&utm_medium=community_answer&utm_campaign=lead_gen`;
  solUrl += (solUrl.includes('?') ? '&' : '') + utm;
}

const postTitle = `[${req.platform.toUpperCase()}] ${req.question_text.slice(0, 100)}`;

return [{
  json: {
    post_url: req.post_url,
    post_title: postTitle,
    platform: req.platform,
    solution_id: matchedSol.id || null,
    solution_title: matchedSol.titleTh || matchedSol.titleEn || null,
    solution_url: data.linkIncluded ? solUrl : null,
    matched_problem: String(data.matchedProblem || req.question_text).slice(0, 500),
    match_score: score,
    relevance_reason: String(data.relevanceReason || `Lead fit: ${data.leadFit}`).slice(0, 500),
    answer: String(data.answer || '').trim(),
    link_included: Boolean(data.linkIncluded),
    link_reason: String(data.linkReason || ''),
    suggested_anchor: String(data.suggestedAnchor || ''),
    status: status,
    is_qualified: isQualified
  }
}];
